import type { TimelineSpan } from "./types";
import type { VoiceMeasures } from "./rhythm";

const EPS = 1e-6;
// Only N coprime to 2 (odd) are detected: for odd N the sole dyadic multiple of
// T/N in (0, T] is T itself, so a dyadic note can never be wrongly absorbed into a
// tuplet region. Even N (e.g. 6) aliases with [dyadic prefix] + [smaller tuplet];
// genuine sextuplets are reducible to two triplet groups and render that way.
const TUPLETS = [3, 5, 7];
const REGION_BEATS = [0.5, 1, 2, 4];
const DYADIC_BEATS = [4, 3, 2, 1.5, 1, 0.75, 0.5, 0.375, 0.25, 0.1875, 0.125, 0.0625];

const isMultiple = (x: number, unit: number): boolean => Math.abs(x / unit - Math.round(x / unit)) < EPS;
const isDyadic = (beats: number): boolean => DYADIC_BEATS.some((d) => Math.abs(d - beats) < EPS);

export function tagTuplets(voices: VoiceMeasures[]): VoiceMeasures[] {
  return voices.map((measures) => measures.map((spans) => tagMeasure(spans)));
}

function tagMeasure(spans: TimelineSpan[]): TimelineSpan[] {
  const out = spans.map((s) => ({ ...s })); // shallow copy: notes arrays are shared with input; this stage only writes `tuplet`.
  let i = 0;
  while (i < out.length) {
    const match = tryRegion(out, i);
    if (match) {
      for (let k = i; k < i + match.count; k++) out[k].tuplet = match.n;
      i += match.count;
    } else {
      i += 1;
    }
  }
  return out;
}

/**
 * Note: a region may start at any span boundary, not necessarily on a beat of the
 * meter (e.g. a triplet region can run from beat 0.25 to 1.25). This is deliberate:
 * the written tuplet durations alone determine timing in alphaTex, so off-grid
 * regions still parse and play correctly, and tuplet groups straddling beat
 * boundaries are legal (if unusual) notation. Requiring grid alignment would force
 * such input down the lossy approximate-duration path instead.
 */
function tryRegion(spans: TimelineSpan[], start: number): { count: number; n: number } | null {
  for (const T of REGION_BEATS) {
    // Gather spans that exactly tile [pos, pos + T).
    let acc = 0;
    let count = 0;
    for (let k = start; k < spans.length; k++) {
      acc += spans[k].durationBeats;
      count++;
      if (acc > T + EPS) break;
      if (Math.abs(acc - T) < EPS) {
        const region = spans.slice(start, start + count);
        const n = matchTuplet(region, T);
        if (n) return { count, n };
        break;
      }
    }
  }
  return null;
}

function matchTuplet(region: TimelineSpan[], T: number): number | null {
  // Skip if every span is already dyadic (a plain split suffices).
  if (region.every((s) => isDyadic(s.durationBeats))) return null;
  for (const n of TUPLETS) {
    const unit = T / n;
    if (region.every((s) => isMultiple(s.durationBeats, unit))) return n;
  }
  return null;
}
