import type { AlphaTexOptions, EmitToken } from "./types";
import { midiToPitchName } from "./pitch";

export interface EmitMeasureModel {
  index: number;
  numerator: number;
  denominator: number;
  tsChange: boolean;
  tokens: EmitToken[];
}

const escapeStr = (s: string): string =>
  s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/[\r\n]+/g, " ");

/**
 * Assemble alphaTex from per-voice, per-measure emit models. `tuningMidi` is core's
 * thin->thick (high->low) order, which is also alphaTex's convention: string K in
 * `fret.K` refers to the K-th entry of the `\tuning` list, and alphaTab's own
 * default guitar tuning lists the high E first. The list is therefore emitted
 * as-is, so core string 0 lines up with alphaTex string 1. The `:N` duration
 * prefix is emitted only when the running value changes; dots and tuplets are
 * per-beat effects. `\ts` is written on voice 0 only (it is a staff property).
 */
export function emitAlphaTex(
  tuningMidi: number[],
  voices: EmitMeasureModel[][],
  options: AlphaTexOptions,
): string {
  const lines: string[] = [];

  const meta: string[] = [];
  if (options.title) meta.push(`\\title "${escapeStr(options.title)}"`);
  if (options.subtitle) meta.push(`\\subtitle "${escapeStr(options.subtitle)}"`);
  // Truthy check on purpose: tempo 0 is not a valid BPM and is treated as unset.
  if (options.tempo) meta.push(`\\tempo ${options.tempo}`);
  if (meta.length) {
    lines.push(...meta);
    lines.push(".");
  }

  const tuningNames = tuningMidi.map(midiToPitchName);
  const label = options.tuningLabel ? ` { label "${escapeStr(options.tuningLabel)}" }` : "";
  lines.push(`\\tuning (${tuningNames.join(" ")})${label}`);

  voices.forEach((measures, vi) => {
    if (voices.length > 1) lines.push("\\voice");
    let runningValue = -1;
    const body = measures.map((m) => {
      const parts: string[] = [];
      if (m.tsChange && vi === 0) parts.push(`\\ts (${m.numerator} ${m.denominator})`);
      for (const tok of m.tokens) {
        if (tok.value !== runningValue) {
          parts.push(`:${tok.value}`);
          runningValue = tok.value;
        }
        parts.push(renderBeat(tok));
      }
      return parts.join(" ");
    });
    lines.push(body.join(" | "));
  });

  return lines.join("\n") + "\n";
}

function renderBeat(tok: EmitToken): string {
  let body: string;
  if (tok.kind === "rest") {
    body = "r";
  } else {
    const notes = tok.notes ?? [];
    const rendered = notes.map((n) => `${n.fret}.${n.string + 1}${tok.tie ? "{t}" : ""}`);
    body = rendered.length === 1 ? rendered[0] : `(${rendered.join(" ")})`;
  }
  const effects: string[] = [];
  if (tok.dotted) effects.push("d");
  if (tok.tuplet) effects.push(`tu ${tok.tuplet}`);
  return effects.length ? `${body}{${effects.join(" ")}}` : body;
}
