import type { AlphaTexOptions, AlphaTexResult, TabData } from "./types";
import { flattenNotes } from "./notes";
import { separateVoices } from "./voices";
import { buildTimelines } from "./rhythm";
import { tagTuplets } from "./tuplets";
import { spansToTokens } from "./durations";
import { emitAlphaTex, type EmitMeasureModel } from "./emit";

const isDefaultMeter = (n: number, d: number): boolean => n === 4 && d === 4;

export function toAlphaTex(data: TabData, options: AlphaTexOptions = {}): AlphaTexResult {
  const maxVoices = options.maxVoices ?? data.tuning.length;
  const { notes, grid } = flattenNotes(data);
  const { voices, warnings: voiceWarnings } = separateVoices(notes, maxVoices);
  const { timelines, warnings: timelineWarnings } = buildTimelines(voices, grid);
  const tagged = tagTuplets(timelines);

  const warnings = [...voiceWarnings, ...timelineWarnings];

  const emitVoices: EmitMeasureModel[][] = tagged.map((measures) =>
    measures.map((spans, mi) => {
      const { tokens, warnings: tokenWarnings } = spansToTokens(spans, String(mi + 1));
      warnings.push(...tokenWarnings);
      const m = grid[mi];
      const prev = mi > 0 ? grid[mi - 1] : undefined;
      const tsChange = prev
        ? m.numerator !== prev.numerator || m.denominator !== prev.denominator
        : !isDefaultMeter(m.numerator, m.denominator);
      return {
        index: mi,
        numerator: m.numerator,
        denominator: m.denominator,
        tsChange,
        tokens,
      };
    }),
  );

  const tex = emitAlphaTex(data.tuning, emitVoices, options);
  return { tex, voiceCount: voices.length, warnings };
}
