import type { MeasureGrid, TimelineSpan, Voice } from "./types";

const EPS = 1e-6;

/** Per voice: an array indexed by measure, each holding that measure's spans. */
export type VoiceMeasures = TimelineSpan[][];

export interface TimelineResult {
  timelines: VoiceMeasures[];
  warnings: string[];
}

export function buildTimelines(voices: Voice[], grid: MeasureGrid): TimelineResult {
  const warnings: string[] = [];
  const timelines = voices.map((voice) => buildVoiceMeasures(voice, grid, warnings));
  return { timelines, warnings };
}

function buildVoiceMeasures(voice: Voice, grid: MeasureGrid, warnings: string[]): VoiceMeasures {
  const result: VoiceMeasures = grid.map(() => []);
  if (grid.length === 0) return result;

  const pieceStart = grid[0].startBeats;
  const last = grid[grid.length - 1];
  const pieceEnd = last.startBeats + last.lengthBeats;

  // Flat timeline across the whole piece: note spans with rests filling every gap.
  const spans: TimelineSpan[] = [];
  let cursor = pieceStart;
  for (const c of voice) {
    if (c.startBeats + c.durationBeats > pieceEnd + EPS) {
      // segmentSpan clips to the grid; surface the loss like every other lossy path.
      warnings.push(
        `note at beat ${c.startBeats} extends past the final barline; clipped to the piece length`,
      );
    }
    if (c.startBeats > cursor + EPS) {
      spans.push({ kind: "rest", startBeats: cursor, durationBeats: c.startBeats - cursor });
    }
    spans.push({ kind: "note", startBeats: c.startBeats, durationBeats: c.durationBeats, notes: c.notes });
    cursor = Math.max(cursor, c.startBeats + c.durationBeats);
  }
  if (pieceEnd > cursor + EPS) {
    spans.push({ kind: "rest", startBeats: cursor, durationBeats: pieceEnd - cursor });
  }

  for (const span of spans) {
    segmentSpan(span, grid, result);
  }
  return result;
}

/** Split a span at measure boundaries, tagging note continuations as tied. */
function segmentSpan(span: TimelineSpan, grid: MeasureGrid, out: VoiceMeasures): void {
  const start = span.startBeats;
  const end = span.startBeats + span.durationBeats;
  let first = true;
  for (const m of grid) {
    const mEnd = m.startBeats + m.lengthBeats;
    if (end <= m.startBeats + EPS || start >= mEnd - EPS) continue;
    const segStart = Math.max(start, m.startBeats);
    const segEnd = Math.min(end, mEnd);
    if (segEnd - segStart <= EPS) continue;
    out[m.index].push({
      kind: span.kind,
      startBeats: segStart,
      durationBeats: segEnd - segStart,
      notes: span.notes,
      tiedFromPrev: span.kind === "note" && !first,
    });
    first = false;
  }
}
