import type { EmitToken, TimelineSpan } from "./types";

const EPS = 1e-6;

/**
 * Canonical alphaTex note values, descending by nominal beat length (quarter = 1).
 * Deliberately omits double-dotted values and the dotted 64th: greedy decomposition
 * in `pushDyadic` covers them with ties instead (e.g. 1.75 beats renders as a dotted
 * quarter tied to a sixteenth rather than a double-dotted quarter).
 */
const TOKENS: { value: number; dotted: boolean; beats: number }[] = [
  { value: 1, dotted: true, beats: 6 },
  { value: 1, dotted: false, beats: 4 },
  { value: 2, dotted: true, beats: 3 },
  { value: 2, dotted: false, beats: 2 },
  { value: 4, dotted: true, beats: 1.5 },
  { value: 4, dotted: false, beats: 1 },
  { value: 8, dotted: true, beats: 0.75 },
  { value: 8, dotted: false, beats: 0.5 },
  { value: 16, dotted: true, beats: 0.375 },
  { value: 16, dotted: false, beats: 0.25 },
  { value: 32, dotted: true, beats: 0.1875 },
  { value: 32, dotted: false, beats: 0.125 },
  { value: 64, dotted: false, beats: 0.0625 },
];

export interface TokenResult {
  tokens: EmitToken[];
  warnings: string[];
}

/** Largest power of two strictly less than n (the standard tuplet denominator). */
// valid for n in {3,5,7}
const tupletPow2 = (n: number): number => (n < 4 ? 2 : 4);

export function spansToTokens(spans: TimelineSpan[], measureLabel: string): TokenResult {
  const tokens: EmitToken[] = [];
  const warnings: string[] = [];

  for (const span of spans) {
    if (span.tuplet) {
      // Decompose the WRITTEN (nominal) duration into dyadic pieces, each carrying the
      // tuplet ratio, so an uneven member (e.g. a 5/7 septuplet member, nominal 1.25)
      // renders as tied tuplet pieces rather than a wrong free note.
      const nominal = (span.durationBeats * span.tuplet) / tupletPow2(span.tuplet);
      if (!pushDyadic(span, tokens, nominal, span.tuplet)) {
        warnings.push(`measure ${measureLabel}: tuplet member ${span.durationBeats} approximated to nearest value`);
      }
      continue;
    }

    if (!pushDyadic(span, tokens, span.durationBeats)) {
      warnings.push(`measure ${measureLabel}: duration ${span.durationBeats} approximated to nearest value`);
    }
  }

  return { tokens, warnings };
}

/**
 * Decompose `totalBeats` into tied dyadic pieces, largest first, each carrying the
 * span's kind/notes and an optional tuplet ratio. Returns false if a sub-64th
 * remainder could not be placed (the placed pieces are then the approximation).
 */
function pushDyadic(span: TimelineSpan, tokens: EmitToken[], totalBeats: number, tuplet?: number): boolean {
  let remaining = totalBeats;
  let first = true;
  let guard = 0;
  while (remaining > EPS && guard++ < 64) {
    const t = TOKENS.find((tok) => tok.beats <= remaining + EPS);
    if (!t) break;
    tokens.push({
      kind: span.kind,
      value: t.value,
      dotted: t.dotted,
      notes: span.notes,
      tuplet,
      tie: span.kind === "note" && (!first || !!span.tiedFromPrev),
    });
    remaining -= t.beats;
    first = false;
  }
  return remaining <= EPS;
}
