const SEMITONES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

/**
 * MIDI note number -> scientific pitch name (C4 = 60), e.g. 40 -> "E2".
 * Mirrors core's `noteNumberToName`; reimplemented locally to keep the adapter
 * free of any runtime dependency on core.
 */
export function midiToPitchName(midi: number): string {
  const octave = Math.floor(midi / 12) - 1;
  const semitone = SEMITONES[((midi % 12) + 12) % 12];
  return `${semitone}${octave}`;
}
