import type { BeatChord, PlacedNote, Voice } from "./types";

const EPS = 1e-6;

export interface VoiceResult {
  voices: Voice[];
  warnings: string[];
}

const topPitch = (chord: BeatChord): number => Math.max(...chord.notes.map((x) => x.midi));

/**
 * Partition notes into voices via greedy interval coloring. Notes sharing an exact
 * (onset, duration) form one beat-chord; overlapping beat-chords go to separate
 * voices. The descending-pitch sort biases voice 0 toward the higher line.
 * `maxVoices` defaults (at the call site) to the string count, which always
 * suffices for physically realizable tab. Overflow merges into the pitch-closest
 * voice by truncating its last chord, and records a warning.
 */
export function separateVoices(notes: PlacedNote[], maxVoices: number): VoiceResult {
  if (maxVoices < 1) return { voices: [], warnings: [] };
  const key = (x: PlacedNote): string => `${x.startBeats.toFixed(6)}:${x.durationBeats.toFixed(6)}`;
  const groups = new Map<string, BeatChord>();
  for (const note of notes) {
    const k = key(note);
    let chord = groups.get(k);
    if (!chord) {
      chord = { startBeats: note.startBeats, durationBeats: note.durationBeats, notes: [] };
      groups.set(k, chord);
    }
    chord.notes.push(note);
  }

  const chords = [...groups.values()].sort(
    (a, b) => a.startBeats - b.startBeats || topPitch(b) - topPitch(a),
  );

  const voices: Voice[] = [];
  const ends: number[] = [];
  const warnings: string[] = [];

  for (const chord of chords) {
    chord.notes.sort((a, b) => b.midi - a.midi);

    let placed = -1;
    for (let v = 0; v < voices.length; v++) {
      if (ends[v] <= chord.startBeats + EPS) {
        placed = v;
        break;
      }
    }

    if (placed === -1 && voices.length < maxVoices) {
      voices.push([]);
      ends.push(0);
      placed = voices.length - 1;
    }

    if (placed === -1) {
      placed = nearestVoiceByPitch(voices, chord);
      const target = voices[placed];
      const last = target[target.length - 1];
      const gap = chord.startBeats - last.startBeats;
      if (gap <= EPS) {
        // Same onset: there is no gap to truncate to. Remove the displaced chord
        // outright (an EPS sliver would be silently dropped at segmentation anyway)
        // and say so, rather than warning "truncated" for a note that disappears.
        target.pop();
        warnings.push(
          `voice overflow at beat ${chord.startBeats}: removed a same-onset ${last.durationBeats}-beat chord to fit maxVoices=${maxVoices}`,
        );
      } else {
        warnings.push(
          `voice overflow at beat ${chord.startBeats}: truncated a ${last.durationBeats}-beat chord to ${gap} to fit maxVoices=${maxVoices}`,
        );
        last.durationBeats = gap;
      }
    }

    voices[placed].push(chord);
    ends[placed] = chord.startBeats + chord.durationBeats;
  }

  return { voices, warnings };
}

function nearestVoiceByPitch(voices: Voice[], chord: BeatChord): number {
  const p = topPitch(chord);
  let best = 0;
  let bestDist = Infinity;
  for (let v = 0; v < voices.length; v++) {
    const last = voices[v][voices[v].length - 1];
    const d = Math.abs(topPitch(last) - p);
    if (d < bestDist) {
      bestDist = d;
      best = v;
    }
  }
  return best;
}
