import type { MeasureGrid, MeasureSpan, PlacedNote, TabData } from "./types";

const QUARTERS_PER_WHOLE = 4;

/** Measure length in quarter-note beats. */
export function measureLengthBeats(numerator: number, denominator: number): number {
  return (numerator * QUARTERS_PER_WHOLE) / denominator;
}

export interface FlattenResult {
  notes: PlacedNote[];
  grid: MeasureGrid;
}

/**
 * Flatten TabData into absolute-positioned notes plus a measure grid derived from
 * the per-measure time signatures. Measure starts are cumulative sums of measure
 * lengths (core aligns time-signature changes to measure boundaries).
 */
export function flattenNotes(data: TabData): FlattenResult {
  const notes: PlacedNote[] = [];
  const grid: MeasureGrid = [];
  let cursor = 0;
  let num = 4;
  let den = 4;

  data.measures.forEach((measure, index) => {
    const change = measure.events.find((e) => e.timeSignatureChange)?.timeSignatureChange;
    if (change) {
      [num, den] = change;
    }
    const lengthBeats = measureLengthBeats(num, den);
    const span: MeasureSpan = {
      index,
      startBeats: cursor,
      lengthBeats,
      numerator: num,
      denominator: den,
    };
    grid.push(span);
    cursor += lengthBeats;

    for (const event of measure.events) {
      if (!event.notes) continue;
      for (const n of event.notes) {
        notes.push({
          startBeats: event.beats,
          durationBeats: n.durationBeats,
          string: n.string,
          fret: n.fret,
          midi: n.midi,
        });
      }
    }
  });

  return { notes, grid };
}
